"""Strict, deterministic JSON boundary handling for the replay contract.

Duplicate object keys, nonfinite constants, invalid UTF-8, empty input and
malformed documents are all rejected with exactly ``{"error":"invalid_json"}``.
UTF-8 BOMs are rejected as well because they are not whitespace to a JSON
parser.
"""

import json
import math

INVALID = '{"error":"invalid_json"}'


def _pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError("duplicate key")
        result[key] = value
    return result


def _finite(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("nonfinite number")
    return value


def _constant(name):
    raise ValueError("nonfinite constant")


def loads(data):
    """Parse raw bytes into strict Python objects."""
    if isinstance(data, (bytes, bytearray)):
        if data.startswith(b"\xef\xbb\xbf"):
            raise ValueError("byte order mark")
        text = data.decode("utf-8")
    else:
        text = data
    if not text.strip():
        raise ValueError("empty input")
    return json.loads(text, object_pairs_hook=_pairs, parse_float=_finite,
                      parse_constant=_constant)


def dumps(document):
    return json.dumps(document, separators=(",", ":"), allow_nan=False)
