"""Replayable telemetry validation pipeline for one stream.

A stream owns independent state: measured counters, demands, the active routing
plan, the process-local repair cache and the frozen snapshots.  Events are the
only way that state moves, and every answer is derived from the replay policy in
PROTOCOL.md, never from wall-clock or filesystem state.
"""

from .common_utils import Topology, Plan, is_int, UNIT
from .dtp import RepairEngine
from .snapshot_cache import RepairCache, SnapshotStore, normalize_inputs
from .validate import Validator

CELL_FIELDS = frozenset(("perturbed", "ground_truth", "corrected", "confidence"))
CELL_ALLOWED = frozenset(("perturbed",)) | CELL_FIELDS


class CrossCheck:
    """Unified repair/validation pipeline for a single topology."""

    def __init__(self, topology):
        self.topology = Topology(topology)
        self.repairer = RepairEngine(self.topology, None)
        self.validator = Validator(self.topology)

    # ------------------------------------------------------------------ state
    def _reset(self, settings):
        topo = self.topology
        self.settings = settings
        self.trials = settings["trials"]
        self.epsilon = settings["epsilon"]
        self.seed = settings["seed"]
        self.cutoff = _fraction(settings["cutoff"])
        self.gamma = _fraction(settings["gamma"])
        self.bias = settings["bias"]
        self.tau = settings["tau"]
        self.counters = {}          # counter key -> reported integer
        self.demands = {}           # (src, dst) -> integer
        self.plan = None            # Plan or None
        self.plan_identity = None
        self.cache = RepairCache(settings["cache_slots"])
        self.snapshots = SnapshotStore()
        self.repairer.settings = settings
        self._loads = None
        self._loads_key = None
        self._dirty = True

    # --------------------------------------------------------------- inputs
    def loads(self):
        """Current predicted load per flow (None where no expectation exists).

        Validation expectations are never rounded beyond the single defined
        floor and never clamped; repair clamps its prediction vote separately.
        """
        if not self._dirty and self._loads is not None:
            return self._loads
        flows = self.topology.flows
        table = [None] * len(flows)
        outgoing = {}
        incoming = {}
        for (src, dst), value in self.demands.items():
            if value:
                outgoing[src] = outgoing.get(src, 0) + value
                incoming[dst] = incoming.get(dst, 0) + value
        for flow in flows:
            if flow.src == -1:
                table[flow.index] = outgoing.get(flow.dst, 0)
            elif flow.dst == -1:
                table[flow.index] = incoming.get(flow.src, 0)
        if self.plan is not None:
            weighted = self.plan.internal_loads(self.demands)
            for index, total in weighted.items():
                table[index] = total // UNIT
        self._loads = table
        self._dirty = False
        return table

    def identity(self):
        return (normalize_inputs(self.counters, self.demands, self.plan_identity),
                self.seed, self.trials, self.epsilon)

    # ----------------------------------------------------------------- events
    def apply_patch(self, event):
        if set(event) != {"op", "demands", "counters"}:
            return False
        demands = event["demands"]
        counters = event["counters"]
        if type(demands) is not list or type(counters) is not dict:
            return False
        topo = self.topology
        staged_demands = {}
        for entry in demands:
            if type(entry) is not list or len(entry) != 3:
                return False
            src, dst, value = entry
            if not (is_int(src) and is_int(dst) and is_int(value)):
                return False
            bound = topo.demand_bound(src, dst)
            if bound is None:
                return False          # invalid pair (unknown/non-external/equal)
            if (src, dst) in staged_demands:
                return False          # repeated pair
            if value < 0 or value > bound:
                return False          # outside the pair's capacity bound
            staged_demands[(src, dst)] = value
        staged_counters = {}
        for key, cell in counters.items():
            index = topo.key_to_flow.get(key)
            if index is None:
                return False          # unknown counter key
            if cell is None:
                staged_counters[key] = None
                continue
            if type(cell) is not dict or "perturbed" not in cell:
                return False
            if not set(cell) <= CELL_ALLOWED:
                return False
            perturbed = cell["perturbed"]
            if perturbed is None:
                staged_counters[key] = None
                continue
            cap = topo.key_cap[key]
            if not is_int(perturbed) or perturbed < 0 or perturbed > cap:
                return False
            staged_counters[key] = perturbed
        self.demands.update(staged_demands)
        for key, value in staged_counters.items():
            if value is None:
                self.counters.pop(key, None)
            else:
                self.counters[key] = value
        self._dirty = True
        return True

    def apply_routes(self, event):
        paths = event["paths"]
        self.plan = None if paths is None else Plan(paths, self.topology)
        self.plan_identity = None if self.plan is None else self.plan.identity
        self._dirty = True
        return True

    def repair(self, event):
        snapshot_id = event["id"]
        key = self.identity()
        payload = self.cache.lookup(key)
        hit = payload is not None
        if payload is None:
            payload = self.repairer.compute(self.counters, self.loads(),
                                           self.plan is not None)
            self.cache.store(key, payload)
        self.snapshots.freeze(snapshot_id, payload)
        return {"op": "repair", "id": snapshot_id, "cache_hit": hit,
                "links": payload["links"], "order": payload["order"],
                "counters": payload["counters"]}

    def validate(self, event):
        snapshot_id = event["id"]
        payload = self.snapshots.get(snapshot_id)
        checked, passed, failed = self.validator.validate(
            payload, self.loads(), self.cutoff, self.bias, self.tau)
        if checked == 0:
            consistent = None
        else:
            num, den = self.gamma
            consistent = passed * den >= checked * num
        return {"op": "validate", "id": snapshot_id, "checked": checked,
                "passed": passed, "consistent": consistent, "failed": failed}

    # ----------------------------------------------------------------- replay
    def replay(self, events, settings):
        self._reset(settings)
        answers = []
        handlers = {"patch": self._event_patch, "routes": self._event_routes,
                    "repair": self.repair, "validate": self.validate}
        for event in events:
            handler = handlers[event["op"]]
            answers.append(handler(event))
        return answers

    def _event_patch(self, event):
        return {"op": "patch", "accepted": self.apply_patch(event)}

    def _event_routes(self, event):
        self.apply_routes(event)
        return {"op": "routes", "accepted": True}


def _fraction(value):
    """Unreduced input fractions are compared by exact cross-multiplication."""
    return (value[0], value[1])
